; ---------------------------------------------------------------------------
; PRG bank 0 ($8000-$BFFF)
; ---------------------------------------------------------------------------

  PAD SHIFT                               ; relocation test, see make.sh

; Spawn the stage enemies. SPECIAL_STAGE places eight type-0 enemies on FIXED_SPAWN_COL/ROW. GAME_MODE nonzero returns. Otherwise LOAD_SPAWN_LIST and place each type until a negative byte.
.SPAWN_STAGE_ENEMIES
  ABS_LDA SPECIAL_STAGE
  BNE L0_8066
  ABS_LDY GAME_MODE
  BNE L0_8020
  JSR LOAD_SPAWN_LIST
  LDY #&00
  STY TEMP4
.L0_8011
  LDY TEMP4
  LDA (DATA_PTR),Y
  BMI L0_801F
  JSR SPAWN_ENEMY_ON_EMPTY
  INC TEMP4
  JMP L0_8011
.L0_801F
  RTS
.L0_8020
  RTS

; A is the enemy type. Random column CELL_COL is 0-31. Row comes from SPAWN_ROW_PICK. Rows under 5 need column at least 5. Map cell must be 0. Then PLACE_ENEMY.
.SPAWN_ENEMY_ON_EMPTY
  STA ENEMY_SPAWN
.L0_8024
  JSR NEXT_RNG
  AND #&1F
  STA CELL_COL
  JSR NEXT_RNG
  AND #&0F
  TAX
  LDY SPAWN_ROW_PICK,X
  STY CELL_ROW
  CPY #&05
  BCS L0_8040
  LDA CELL_COL
  CMP #&05
  BCC L0_8024
.L0_8040
  LDA MAP_ROW_LO,Y
  STA MAP_PTR
  LDA MAP_ROW_HI,Y
  STA MAP_PTR_HI
  LDY CELL_COL
  LDA (MAP_PTR),Y
  BNE L0_8024
  LDA ENEMY_SPAWN
  JMP PLACE_ENEMY

; 16 row numbers. SPAWN_ENEMY_ON_EMPTY indexes this with RNG and 0F.
.SPAWN_ROW_PICK
  EQUB &01,&02,&03,&04,&05,&06,&07,&08,&09,&0A,&0B,&03,&04,&05,&06,&07

; (not seen executing during the coverage runs)
.L0_8066
  LDA #&07
  STA TEMP4
.L0_806A
  LDX TEMP4
  LDA FIXED_SPAWN_COL,X
  STA CELL_COL
  LDA FIXED_SPAWN_ROW,X
  STA CELL_ROW
  LDA #&00
  JSR PLACE_ENEMY
  DEC TEMP4
  BPL L0_806A
  RTS

; Eight columns for the SPECIAL_STAGE fixed spawns. Paired with FIXED_SPAWN_ROW. Not pointers.
.FIXED_SPAWN_COL
  EQUB &03,&03,&05,&07,&07,&09,&09,&0B

; Eight rows for the SPECIAL_STAGE fixed spawns. Paired with FIXED_SPAWN_COL.
.FIXED_SPAWN_ROW
  EQUB &03,&07,&05,&05,&09,&03,&07,&07

; (not seen executing during the coverage runs)

; Every 4th frame, place a type-0 enemy on the next PARADE_SPAWN_COL/ROW point. PARADE_IDX walks 0 through 64. Also runs SPAWN_TYPE_10.
.SPAWN_PARADE
  JSR SPAWN_TYPE_10
  LDA FRAME_CNT
  AND #&03
  BNE L0_80B5
  LDY PARADE_IDX
  LDA PARADE_SPAWN_COL,Y
  STA CELL_COL
  LDA PARADE_SPAWN_ROW,Y
  STA CELL_ROW
  LDA #&00
  JSR PLACE_ENEMY
  INY
  CPY #&41
  BCC L0_80B2
  LDY #&00
.L0_80B2
  STY PARADE_IDX
.L0_80B5
  RTS

; Place enemy type 16. TYPE10_TRY at least 16 tries once, then stores FF on success. If TYPE10_TRY is negative and TYPE10_ARM is positive, count TYPE10_TIME down and try again.
.SPAWN_TYPE_10
  LDA TYPE10_TRY
  BMI L0_80CC
  CMP #&10
  BCC L0_80CB
  LDA #&10
  JSR PLACE_ENEMY
  BCC L0_80CB
  LDA #&FF
  STA TYPE10_TRY
.L0_80CB
  RTS
.L0_80CC
  LDA TYPE10_ARM
  BEQ L0_80E4
  BMI L0_80E4
  DEC TYPE10_TIME
  BNE L0_80E4
  LDA #&10
  JSR PLACE_ENEMY
  BCC L0_80E5
  LDA #&FF
  STA TYPE10_ARM
.L0_80E4
  RTS
.L0_80E5
  INC TYPE10_TIME
  RTS

; If TYPE10_ARM is 0, set it to 1 and TYPE10_TIME to F0. The type 10 hex AI bytes call this when the phase is 0.
.ARM_TYPE10_TIMER
  LDA TYPE10_ARM
  BNE L0_80F6
  INC TYPE10_ARM
  LDA #&F0
  STA TYPE10_TIME
.L0_80F6
  RTS

; 65 columns for SPAWN_PARADE. PARADE_SPAWN_ROW is the matching row list.
.PARADE_SPAWN_COL
  EQUB &03,&03,&03,&03,&03,&05,&05,&05,&05,&05,&07,&07,&07,&07,&07,&09
  EQUB &09,&09,&09,&09,&0B,&0B,&0B,&0B,&0B,&0D,&0D,&0D,&0D,&0D,&0F,&0F
  EQUB &0F,&0F,&0F,&11,&11,&11,&11,&11,&13,&13,&13,&13,&13,&15,&15,&15
  EQUB &15,&15,&17,&17,&17,&17,&17,&19,&19,&19,&19,&19,&1B,&1B,&1B,&1B
  EQUB &1B

; 65 rows for SPAWN_PARADE. Index is PARADE_IDX, same index as PARADE_SPAWN_COL.
.PARADE_SPAWN_ROW
  EQUB &01,&03,&05,&07,&09,&0B,&09,&07,&05,&03,&01,&03,&05,&07,&09,&0B
  EQUB &09,&07,&05,&03,&01,&03,&05,&07,&09,&0B,&09,&07,&05,&03,&01,&03
  EQUB &05,&07,&09,&0B,&09,&07,&05,&03,&01,&03,&05,&07,&09,&0B,&09,&07
  EQUB &05,&03,&01,&03,&05,&07,&09,&0B,&09,&07,&05,&03,&01,&03,&05,&07
  EQUB &09

; When BURST_TIME hits 0, place eight copies of one type from BURST_TYPE_LIST (types 1-4), chosen by RNG, at cell BURST_COL / BURST_ROW.
.SPAWN_BURST
  LDA BURST_TIME
  BEQ L0_81A1

; (not seen executing during the coverage runs)
  DEC BURST_TIME
  BNE L0_81A1
  LDA BURST_COL
  STA CELL_COL
  LDA BURST_ROW
  STA CELL_ROW
  LDA #&08
  STA TEMP4
  JSR NEXT_RNG
  AND #&03
  TAY
.L0_8197
  LDA BURST_TYPE_LIST,Y
  JSR PLACE_ENEMY
  DEC TEMP4
  BNE L0_8197
.L0_81A1
  RTS

; Four enemy types, 1 through 4. SPAWN_BURST picks one with RNG and 03.
.BURST_TYPE_LIST
  EQUB &01,&02,&03,&04

; When TYPE4_TIME hits 0, place one type-4 enemy at cell TYPE4_COL / TYPE4_ROW.
.SPAWN_TYPE_4
  LDA TYPE4_TIME
  BEQ L0_81BF

; (not seen executing during the coverage runs)
  DEC TYPE4_TIME
  BNE L0_81BF
  LDA TYPE4_COL
  STA CELL_COL
  LDA TYPE4_ROW
  STA CELL_ROW
  LDA #&04
  JMP PLACE_ENEMY
.L0_81BF
  RTS

; Place enemy type A at cell CELL_COL, CELL_ROW. Pixel is cell*16+8. Clears the slot timers. Carry set when a slot was free.
.PLACE_ENEMY
  STA ENEMY_PLACE
  JSR FIND_FREE_ENEMY
  BCS L0_820E
  LDA CELL_COL
  STA ENEMY_COL,X
  ASL A
  ASL A
  ASL A
  ASL A
  ORA #&08
  STA ENEMY_X,X
  ROL A
  AND #&01
  STA ENEMY_X_HI,X
  LDA CELL_ROW
  STA ENEMY_ROW,X
  ASL A
  ASL A
  ASL A
  ASL A
  ORA #&08
  STA ENEMY_Y,X
  LDA ENEMY_PLACE
  STA ENEMY_TYPE,X
  LDA #&01
  STA ENEMY_FLAGS,X
  LDA #&00
  STA ENEMY_SCORE,X
  STA ENEMY_PHASE,X
  STA ENEMY_ACC,X
  STA ENEMY_TIMER,X
  STA ENEMY_DIR,X
  STA ENEMY_SUBT,X
  STA ENEMY_SCRIPT,X
  SEC
  RTS

; (not seen executing during the coverage runs)
.L0_820E
  CLC
  RTS

; Find slot 9..0 whose ENEMY_FLAGS is 0. X is the slot and carry is clear. Carry set if all 10 slots are used.
.FIND_FREE_ENEMY
  LDX #&09
.L0_8212
  LDA ENEMY_FLAGS,X
  BEQ L0_821C
  DEX
  BPL L0_8212

; (not seen executing during the coverage runs)
  SEC
  RTS
.L0_821C
  CLC
  RTS

; Clear ENEMIES_GONE if any slot is active, not negative, and not type 17. If every slot is empty or type 17, set ENEMIES_GONE once. BURST_TIME or TYPE4_TIME also clears it.
.NOTE_ENEMIES_CLEARED
  LDA BURST_TIME
  ORA TYPE4_TIME
  BNE L0_8249
  LDX #&09
.L0_8228
  LDA ENEMY_FLAGS,X
  BEQ L0_8236
  BMI L0_8236
  LDA ENEMY_TYPE,X
  CMP #&11
  BNE L0_8249
.L0_8236
  DEX
  BPL L0_8228
  LDA ENEMIES_GONE
  BNE L0_8248
  LDA #&01
  STA ENEMIES_GONE
  ABS_LDA SPECIAL_STAGE
  BNE L0_8248
.L0_8248
  RTS
.L0_8249
  LDA #&00
  STA ENEMIES_GONE
  RTS

; Enemy logic for slot X. Negative ENEMY_FLAGS goes to ENEMY_DEATH_STEP. Otherwise jump through ENEMY_AI_LO indexed by ENEMY_TYPE.
.DISPATCH_ENEMY_AI
  BMI L0_8263
  LDA ENEMY_TYPE,X
  ASL A
  TAY
  LDA ENEMY_AI_LO,Y
  STA DATA_PTR
  LDA D0_8267,Y
  STA DATA_PTR_HI
  JMP (DATA_PTR)
.L0_8263
  JMP ENEMY_DEATH_STEP

; Logic entry for each enemy type, little-endian. Index is ENEMY_TYPE. A few entries are still raw words inside the table.
.ENEMY_AI_LO
  EQUB LO(ENEMY_AI_00)
.D0_8267
  EQUB HI(ENEMY_AI_00)
  EQUW ENEMY_AI_01
  EQUW ENEMY_AI_02
  EQUW ENEMY_AI_03
  EQUW ENEMY_AI_04
  EQUW ENEMY_AI_05
  EQUW ENEMY_AI_06
  EQUW ENEMY_AI_07
  EQUW ENEMY_AI_08
  EQUW ENEMY_AI_09
  EQUW ENEMY_AI_10
  EQUW ENEMY_AI_11
  EQUW ENEMY_AI_12
  EQUW ENEMY_AI_13
  EQUW ENEMY_AI_14
  EQUW ENEMY_AI_15
  EQUW ENEMY_AI_16
  EQUW ENEMY_AI_17
  EQUW ENEMY_AI_18
  EQUW ENEMY_AI_19
  EQUW ENEMY_AI_20
  EQUW ENEMY_AI_21
  EQUW ENEMY_AI_22
  EQUW ENEMY_AI_23
  EQUW ENEMY_AI_24
  EQUW ENEMY_AI_25
  EQUW ENEMY_AI_26

; Draw enemy ENEMY_INDEX. Skip if ENEMY_FLAGS is 0 or bit 4 is set. Bit 3 draws on even frames only. Jump through ENEMY_DRAW_LO indexed by type.
.DISPATCH_ENEMY_DRAW
  LDX ENEMY_INDEX
  LDA ENEMY_FLAGS,X
  BEQ L0_82C6
  AND #&10
  BNE L0_82C6
  LDA ENEMY_FLAGS,X
  AND #&08
  BEQ L0_82B4
  LDA FRAME_CNT
  LSR A
  BCC L0_82C6
.L0_82B4
  LDA ENEMY_TYPE,X
  ASL A
  TAY
  LDA ENEMY_DRAW_LO,Y
  STA DATA_PTR
  LDA D0_82C8,Y
  STA DATA_PTR_HI
  JMP (DATA_PTR)
.L0_82C6
  RTS

; Draw entry for each enemy type. Same index as ENEMY_AI_LO.
.ENEMY_DRAW_LO
  EQUB LO(DRAW_ENEMY_00)
.D0_82C8
  EQUB HI(DRAW_ENEMY_00)
  EQUW DRAW_ENEMY_01
  EQUW DRAW_ENEMY_02
  EQUW DRAW_ENEMY_03
  EQUW DRAW_ENEMY_04
  EQUW DRAW_ENEMY_05
  EQUW DRAW_ENEMY_06
  EQUW DRAW_ENEMY_07
  EQUW DRAW_ENEMY_08
  EQUW DRAW_ENEMY_09
  EQUW DRAW_ENEMY_10
  EQUW DRAW_ENEMY_11
  EQUW DRAW_ENEMY_12
  EQUW DRAW_ENEMY_13
  EQUW DRAW_ENEMY_14
  EQUW DRAW_ENEMY_15
  EQUW DRAW_ENEMY_16
  EQUW DRAW_ENEMY_17
  EQUW DRAW_ENEMY_FRAME
  EQUW DRAW_ENEMY_18
  EQUW DRAW_ENEMY_20
  EQUW DRAW_ENEMY_21
  EQUW DRAW_ENEMY_22
  EQUW DRAW_ENEMY_23
  EQUW DRAW_ENEMY_24
  EQUW DRAW_ENEMY_25
  EQUW DRAW_ENEMY_26
.L0_82FD
  RTS

; Slot ENEMY_INDEX. Bit 0 of ENEMY_REACT clear: a map cell with bit 7 starts death (ENEMY_FLAGS = 80, timer 30) unless bit 6 is set, and adds ENEMY_SCORE_INDEX. Bit 0 set: overlap with the player. Type 16 gives a life and sound 0A. Other types jump L7_CEC4. SPECIAL_STAGE only allows type 16.
.ENEMY_BLAST_OR_PLAYER
  LDX ENEMY_INDEX
  LDA ENEMY_REACT
  LSR A
  BCS L0_835F
  LDA ENEMY_FLAGS,X
  BEQ L0_82FD
  BMI L0_82FD
  AND #&40
  BNE L0_835E
  LDY ENEMY_ROW,X
  STY CELL_ROW
  LDA MAP_ROW_LO,Y
  STA MAP_PTR
  LDA MAP_ROW_HI,Y
  STA MAP_PTR_HI
  LDY ENEMY_COL,X
  STY CELL_COL
  LDA (MAP_PTR),Y
  AND #&80
  BEQ L0_835E
  LDA #&80
  STA ENEMY_FLAGS,X
  LDA #&00
  STA ENEMY_PHASE,X
  LDA #&30
  STA ENEMY_ACC,X
  JSR FIND_ACTOR_CELL
  LDA FLAME_OWNER,Y
  TAY
  LDA RING_SLOT,Y
  PHA
  CMP #&03
  BCS L0_8350
  CLC
  ADC #&01
  STA RING_SLOT,Y
.L0_8350
  PLA
  LDY ENEMY_TYPE,X
  CLC
  ADC ENEMY_SCORE_INDEX,Y
  STA ENEMY_SCORE,X
  LDA RING_SLOT,Y
.L0_835E
  RTS
.L0_835F
  LDA ACTOR_DEATH
  BNE L0_8392
  LDA ENEMY_FLAGS,X
  BEQ L0_8392
  BMI L0_8392
  AND #&20
  BNE L0_8392
  ABS_LDA SPECIAL_STAGE
  BEQ L0_837A

; (not seen executing during the coverage runs)
  LDA ENEMY_TYPE,X
  CMP #&10
  BNE L0_8392
.L0_837A
  LDA ENEMY_X,X
  SEC
  ABS_SBC ACTOR_X
  TAY
.L0_8382
  LDA ENEMY_X_HI,X
  ABS_SBC ACTOR_XSUB
  BEQ L0_8393
  CMP #&FF
  BNE L0_8392
  CPY #&F6
  BCS L0_8397
.L0_8392
  RTS
.L0_8393
  CPY #&0A
  BCS L0_8392
.L0_8397
  LDA ENEMY_Y,X
  SEC
  ABS_SBC ACTOR_Y
  CMP #&0A
  BCC L0_83A6
  CMP #&F6
  BCC L0_83BD
.L0_83A6
  LDA ENEMY_TYPE,X
  CMP #&10
  BEQ L0_83B0
  JMP L7_CEC4

; (not seen executing during the coverage runs)
.L0_83B0
  INC LIVES
  LDA #&00
  STA ENEMY_FLAGS,X
  LDA #&0A
  JSR AUDIO_CALL
.L0_83BD
  RTS

; Draw all 10 enemies. ENEMY_ORDER = 0 uses order phase 0. Otherwise FRAME_CNT picks one of four rotations in ENEMY_DRAW_ORDER.
.DRAW_ALL_ENEMIES
  LDA ENEMY_ORDER
  BEQ L0_83C5
  LDA FRAME_CNT
.L0_83C5
  AND #&03
  TAX
  LDA ENEMY_ORDER_BASE,X
  STA DRAW_PHASE
  LDA #&09
  STA TEMP4
.L0_83D2
  LDA TEMP4
  CLC
  ADC DRAW_PHASE
  TAX
  LDA ENEMY_DRAW_ORDER,X
  STA ENEMY_INDEX
  JSR DISPATCH_ENEMY_DRAW
  DEC TEMP4
  BPL L0_83D2
  RTS

; Four offsets into ENEMY_DRAW_ORDER: 0, 10, 20, 30. DRAW_ALL_ENEMIES picks one with FRAME_CNT bits 0 and 1, unless ENEMY_ORDER is 0.
.ENEMY_ORDER_BASE
  EQUB &00,&0A,&14,&1E

; 40 slot indexes, four rotations of 10. DRAW_ALL_ENEMIES adds ENEMY_ORDER_BASE and draws in that order.
.ENEMY_DRAW_ORDER
  EQUB &00,&01,&02,&03,&04,&05,&06,&07,&08,&09,&08,&09,&06,&07,&03,&04
  EQUB &05,&00,&01,&02,&03,&04,&05,&00,&01,&02,&08,&09,&06,&07,&06,&07
  EQUB &08,&09,&03,&04,&05,&00,&01,&02

; Slot X: tile column from the 16-bit pixel X, tile row from pixel Y shifted right 4.
.ENEMY_PIX_TO_CELL
  LDA ENEMY_X_HI,X
  LSR A
  LDA ENEMY_X,X
  ROR A
  LSR A
  LSR A
  LSR A
  STA ENEMY_COL,X
  LDA ENEMY_Y,X
  LSR A
  LSR A
  LSR A
  LSR A
  STA ENEMY_ROW,X
  RTS

; Copy the enemy pixel X and Y+32 into SPR_X-SPR_Y for DRAW_METASPRITE.
.ENEMY_LOAD_DRAW_POS
  LDA ENEMY_X,X
  ABS_STA SPR_X
  LDA ENEMY_X_HI,X
  ABS_STA SPR_X_HI
  LDA ENEMY_Y,X
  CLC
  ADC #&20
  ABS_STA SPR_Y
  RTS

; Move slot X one pixel. A is 0 up, 1 left, 2 down, 3 right. Left and right use the high byte ENEMY_X_HI.
.ENEMY_MOVE_1
  TAY
  BEQ L0_844F
  DEY
  BEQ L0_8460
  DEY
  BEQ L0_8453
  DEY
  BEQ L0_8457

; (not seen executing during the coverage runs)
  RTS
.L0_844F
  DEC ENEMY_Y,X
  RTS
.L0_8453
  INC ENEMY_Y,X
  RTS
.L0_8457
  INC ENEMY_X,X
  BNE L0_845F
  INC ENEMY_X_HI,X
.L0_845F
  RTS
.L0_8460
  DEC ENEMY_X,X
  LDA ENEMY_X,X
  CMP #&FF
  BNE L0_846D
  DEC ENEMY_X_HI,X
.L0_846D
  RTS

; Same directions as ENEMY_MOVE_1, stepping by ENEMY_STEP pixels.
.ENEMY_MOVE_SPEED
  TAY
  BEQ L0_847B
  DEY
  BEQ L0_8486

; (not seen executing during the coverage runs)
  DEY
  BEQ L0_8499
  DEY
  BEQ L0_84A4
  RTS
.L0_847B
  LDA ENEMY_Y,X
  SEC
  SBC ENEMY_STEP
  STA ENEMY_Y,X
  RTS
.L0_8486
  LDA ENEMY_X,X
  SEC
  SBC ENEMY_STEP
  STA ENEMY_X,X
  LDA ENEMY_X_HI,X
  SBC #&00
  STA ENEMY_X_HI,X
  RTS

; (not seen executing during the coverage runs)
.L0_8499
  LDA ENEMY_Y,X
  CLC
  ADC ENEMY_STEP
  STA ENEMY_Y,X
  RTS
.L0_84A4
  LDA ENEMY_X,X
  CLC
  ADC ENEMY_STEP
  STA ENEMY_X,X
  LDA ENEMY_X_HI,X
  ADC #&00
  STA ENEMY_X_HI,X
  RTS

; Carry set if direction A is blocked for slot X. The enemy must be near a cell edge. Then the map cell ahead is masked with ENEMY_MASK.
.ENEMY_DIR_BLOCKED
  TAY
  BNE L0_84BD
  JMP L0_8551
.L0_84BD
  DEY
  BEQ L0_84F9
  DEY
  BEQ L0_8525
  LDA ENEMY_Y,X
  AND #&1F
  CMP #&18
  BEQ L0_84CF
  JMP L0_857D
.L0_84CF
  LDA ENEMY_X,X
  AND #&0F
  CMP #&08
  BCS ENEMY_BLOCK_RIGHT
  JMP L0_857B

; Carry set if the map cell to the right, masked by ENEMY_MASK, is nonzero.
.ENEMY_BLOCK_RIGHT
  LDY ENEMY_ROW,X
  LDA MAP_ROW_LO,Y
  STA MAP_PTR
  LDA MAP_ROW_HI,Y
  STA MAP_PTR_HI
  LDY ENEMY_COL,X
  INY
  LDA (MAP_PTR),Y
  AND ENEMY_MASK
  BNE L0_84F6
  JMP L0_857B
.L0_84F6
  JMP L0_857D
.L0_84F9
  LDA ENEMY_Y,X
  AND #&1F
  CMP #&18
  BNE L0_857D
  LDA ENEMY_X,X
  AND #&0F
  CMP #&09
  BCS L0_857B

; Carry set if the map cell to the left, masked by ENEMY_MASK, is nonzero.
.ENEMY_BLOCK_LEFT
  LDY ENEMY_ROW,X
  LDA MAP_ROW_LO,Y
  STA MAP_PTR
  LDA MAP_ROW_HI,Y
  STA MAP_PTR_HI
  LDY ENEMY_COL,X
  DEY
  LDA (MAP_PTR),Y
  AND ENEMY_MASK
  BEQ L0_857B
  BNE L0_857D
.L0_8525
  LDA ENEMY_X,X
  AND #&1F
  CMP #&18
  BNE L0_857D
  LDA ENEMY_Y,X
  AND #&0F
  CMP #&08
  BCC L0_857B

; Carry set if the map cell below, masked by ENEMY_MASK, is nonzero.
.ENEMY_BLOCK_DOWN
  LDY ENEMY_ROW,X
  INY
  LDA MAP_ROW_LO,Y
  STA MAP_PTR
  LDA MAP_ROW_HI,Y
  STA MAP_PTR_HI
  LDY ENEMY_COL,X
  LDA (MAP_PTR),Y
  AND ENEMY_MASK
  BEQ L0_857B
  BNE L0_857D
.L0_8551
  LDA ENEMY_X,X
  AND #&1F
  CMP #&18
  BNE L0_857D
  LDA ENEMY_Y,X
  AND #&0F
  CMP #&09
  BCS L0_857B

; Carry set if the map cell above, masked by ENEMY_MASK, is nonzero.
.ENEMY_BLOCK_UP
  LDY ENEMY_ROW,X
  DEY
  LDA MAP_ROW_LO,Y
  STA MAP_PTR
  LDA MAP_ROW_HI,Y
  STA MAP_PTR_HI
  LDY ENEMY_COL,X
  LDA (MAP_PTR),Y
  AND ENEMY_MASK
  BNE L0_857D
.L0_857B
  CLC
  RTS
.L0_857D
  SEC
  RTS

; Direction toward the player cell ACTOR_COL / ACTOR_ROW. The larger axis wins. 0 up, 1 left, 2 down, 3 right.
.ENEMY_AIM_PLAYER
  LDY #&03
  LDA ACTOR_COL
  SEC
.L0_8584
  SBC ENEMY_COL,X
  BPL L0_8590
  LDY #&01
  EOR #&FF
  CLC
  ADC #&01
.L0_8590
  STA TEMP1
  STY TEMP2
  LDY #&02
  LDA ACTOR_ROW
  SEC
  SBC ENEMY_ROW,X
  BPL L0_85A5
  LDY #&00
  EOR #&FF
  CLC
  ADC #&01
.L0_85A5
  CMP TEMP1
  BCS L0_85AB
  LDY TEMP2
.L0_85AB
  TYA
  RTS

; If the current direction is horizontal, return up or down toward ACTOR_ROW. If vertical, return left or right toward ACTOR_COL.
.ENEMY_STRAFE_AXIS
  LDA ENEMY_DIR,X
  AND #&01
  BEQ L0_85C0
  LDA #&00
  LDY ENEMY_ROW,X
  CPY ACTOR_ROW
  BCS L0_85BF
  LDA #&02
.L0_85BF
  RTS
.L0_85C0
  LDA #&01
  LDY ENEMY_COL,X
  CPY ACTOR_COL
  BCS L0_85CB
  LDA #&03
.L0_85CB
  RTS

; Z set when both pixel X and Y are 18 hex mod 20 hex, the center of an odd cell.
.ENEMY_AT_ODD_CENTER
  LDA ENEMY_X,X
  AND #&1F
  CMP #&18
  BNE L0_85DC
  LDA ENEMY_Y,X
  AND #&1F
  CMP #&18
.L0_85DC
  RTS

; Z set when both pixel X and Y are 8 mod 16, the center of any cell.
.ENEMY_AT_CELL_CENTER
  LDA ENEMY_X,X
  AND #&0F
  CMP #&08
  BNE L0_85DC
  LDA ENEMY_Y,X
  AND #&0F
  CMP #&08
  RTS

; Set bit 6 of ENEMY_FLAGS so ENEMY_BLAST_OR_PLAYER skips the blast reaction.
.ENEMY_SET_NOBLAST
  LDA ENEMY_FLAGS,X
  ORA #&40
  STA ENEMY_FLAGS,X
  RTS

; (not seen executing during the coverage runs)

; Clear bit 6 of ENEMY_FLAGS.
.ENEMY_CLR_NOBLAST
  LDA ENEMY_FLAGS,X
  AND #&BF
  STA ENEMY_FLAGS,X
  RTS

; Clear bits 3 and 4 of ENEMY_FLAGS (flicker and no-draw).
.ENEMY_CLR_VIS_BITS
  LDA ENEMY_FLAGS,X
  AND #&E7
  STA ENEMY_FLAGS,X
  RTS

; Set bit 3 and clear bit 4 of ENEMY_FLAGS. Draw runs on even frames only.
.ENEMY_SET_FLICKER
  LDA ENEMY_FLAGS,X
  AND #&EF
  ORA #&08
  STA ENEMY_FLAGS,X
  RTS

; Set bit 4 and clear bit 3 of ENEMY_FLAGS. DISPATCH_ENEMY_DRAW skips the slot.
.ENEMY_SET_NODRAW
  LDA ENEMY_FLAGS,X
  AND #&F7
  ORA #&10
  STA ENEMY_FLAGS,X
  RTS

; (not seen executing during the coverage runs)
.L0_861F
  LDA ENEMY_FLAGS,X
  AND #&DF
  STA ENEMY_FLAGS,X
  RTS
.L0_8628
  LDA ENEMY_FLAGS,X
  ORA #&20
  STA ENEMY_FLAGS,X
  RTS

; Try directions 0, 1, 3, then 2. Keep the first one ENEMY_DIR_BLOCKED accepts.
.ENEMY_TRY_FOUR_DIRS
  LDA #&00
  STA ENEMY_DIR,X
  JSR ENEMY_DIR_BLOCKED
  BCC L0_8657
  LDA #&01
  STA ENEMY_DIR,X
  JSR ENEMY_DIR_BLOCKED
  BCC L0_8657
  LDA #&03
  STA ENEMY_DIR,X
  JSR ENEMY_DIR_BLOCKED
  BCC L0_8657
  LDA #&02
  STA ENEMY_DIR,X
  JSR ENEMY_DIR_BLOCKED
.L0_8657
  RTS

; Pick a random direction. If it is blocked, try up, left, right, then down via the single-cell tests.
.ENEMY_RANDOM_OPEN_DIR
  JSR NEXT_RNG
  AND #&03
  STA ENEMY_DIR,X
  JSR ENEMY_DIR_BLOCKED
  BCC L0_868E
  LDA #&00
  STA ENEMY_DIR,X
  JSR ENEMY_BLOCK_UP
  BCC L0_868E
  LDA #&01
  STA ENEMY_DIR,X
  JSR ENEMY_BLOCK_LEFT
  BCC L0_868E
  LDA #&03
  STA ENEMY_DIR,X
  JSR ENEMY_BLOCK_RIGHT
  BCC L0_868E
  LDA #&02
  STA ENEMY_DIR,X
  JSR ENEMY_BLOCK_DOWN
  BCC L0_868E
  RTS
.L0_868E
  INC ENEMY_PHASE,X
  RTS

; If the reverse of ENEMY_DIR is open, store it.
.ENEMY_REVERSE_IF_OPEN
  LDA ENEMY_DIR,X
  EOR #&02
  PHA
  JSR ENEMY_DIR_BLOCKED
  PLA
  BCS L0_86A1
  STA ENEMY_DIR,X
.L0_86A1
  RTS

; Turn by a delta from ENEMY_TURN_DELTAS. Eight groups of four deltas. Keep the first open direction.
.ENEMY_PICK_TURN
  JSR NEXT_RNG
  AND #&07
  ASL A
  ASL A
  STA TEMP1
  LDA #&04
  STA TEMP2
.L0_86AF
  LDY TEMP1
  LDA ENEMY_TURN_DELTAS,Y
  CLC
  ADC ENEMY_DIR,X
  AND #&03
  STA TEMP3
  JSR ENEMY_DIR_BLOCKED
  BCC L0_86CD
  INC TEMP1
  DEC TEMP2
  BNE L0_86AF

; (not seen executing during the coverage runs)
  LDA #&02
  STA ENEMY_DIR,X
  RTS
.L0_86CD
  LDA TEMP3
  STA ENEMY_DIR,X
  RTS

; 32 direction deltas. ENEMY_PICK_TURN chooses one of eight groups of four with RNG, then keeps the first open direction.
.ENEMY_TURN_DELTAS
  EQUB &00,&01,&03,&02,&00,&03,&01,&02,&01,&00,&03,&02,&01,&03,&00,&02
  EQUB &03,&00,&01,&02,&03,&01,&00,&02,&03,&01,&00,&02,&01,&03,&00,&02

; Carry set if any blast slot BOMB_FLAG shares this enemy column or row.
.ENEMY_ON_BLAST_LINE
  LDY #&17
.L0_86F5
  LDA BOMB_FLAG,Y
  BEQ L0_870A
  LDA ENEMY_COL,X
  CMP BOMB_COL,Y
  BEQ L0_870F
  LDA ENEMY_ROW,X
  CMP BOMB_ROW,Y
  BEQ L0_870F
.L0_870A
  DEY
  BPL L0_86F5
  CLC
  RTS
.L0_870F
  SEC
  RTS

; Death timer. After six steps, ENEMY_FLAGS becomes 61 hex, the old type is saved, the type becomes 17, then L7_D192.
.ENEMY_DEATH_STEP
  DEC ENEMY_ACC,X
  BNE L0_8740
  LDA #&0A
  STA ENEMY_ACC,X
  INC ENEMY_PHASE,X
  LDA ENEMY_PHASE,X
  CMP #&06
  BCC L0_8740
  LDA #&61
  STA ENEMY_FLAGS,X
  LDA #&00
  STA ENEMY_ACC,X
  LDA ENEMY_TYPE,X
  STA ENEMY_PHASE,X
  LDA #&11
  STA ENEMY_TYPE,X
  LDY ENEMY_SCORE,X
  JMP L7_D192
.L0_8740
  RTS

