; Type 3. Mask 50 hex. After two odd-cell centers, face the player with ENEMY_AIM_PLAYER.
.ENEMY_AI_03
  LDA #&50
  STA ENEMY_MASK
  LDA ENEMY_ACC,X
  CLC
  ADC #&80
  STA ENEMY_ACC,X
  BCC L0_88DC
  LDA ENEMY_PHASE,X
  BEQ L0_88EE
  LDA ENEMY_DIR,X
  JSR ENEMY_DIR_BLOCKED
  BCS L0_88DD
  LDA ENEMY_DIR,X
  JSR ENEMY_MOVE_1
  JSR ENEMY_PIX_TO_CELL
  LDA ENEMY_X,X
  AND #&1F
  CMP #&18
  BNE L0_88DC
  LDA ENEMY_Y,X
  AND #&1F
  CMP #&18
  BNE L0_88DC
  INC ENEMY_TIMER,X
  LDA ENEMY_TIMER,X
  CMP #&02
  BCC L0_88DC
  JSR ENEMY_AIM_PLAYER
  STA ENEMY_DIR,X
  LDA #&00
  STA ENEMY_TIMER,X
.L0_88DC
  RTS
.L0_88DD
  LDA ENEMY_DIR,X
  CLC
  ADC #&01
  AND #&03
  STA ENEMY_DIR,X
  LDA #&00
  STA ENEMY_TIMER,X
  RTS
.L0_88EE
  JSR NEXT_RNG
  AND #&03
  STA ENEMY_DIR,X
  AND #&01
  STA ENEMY_TIMER,X
  INC ENEMY_PHASE,X
  RTS

; Type 3 draw. Point DATA_PTR at ENEMY_WALK_03 and jump DRAW_ENEMY_WALK.

; JP: DATA_PTR = D0_AB16 / US: DATA_PTR = ENEMY_WALK_03.
.DRAW_ENEMY_03
  LDA D0_890C
  STA DATA_PTR
  LDA D0_890D
  STA DATA_PTR_HI
  JMP DRAW_ENEMY_WALK
.D0_890C
  EQUB LO(D0_AB16)
.D0_890D
  EQUB HI(D0_AB16)

