; Type 6 draw. Phases 3 through 5 pick a metasprite from the walk table plus 11 hex or 16 hex. Other phases use DRAW_ENEMY_WALK. A negative ENEMY_FLAGS also uses the walker.
.DRAW_ENEMY_06
