  TAY
  LDA D0_8BFB
  STA DATA_PTR
  LDA D0_8BFC
  STA DATA_PTR_HI
  LDA (DATA_PTR),Y
  STA SPR_PTR
  INY
  LDA (DATA_PTR),Y
  STA SPR_PTR_HI
  LDA #&20
  ABS_STA SPR_FLIP
  JSR ENEMY_LOAD_DRAW_POS
  JMP DRAW_METASPRITE
.L0_8BEE
  LDA D0_8BFB
  STA DATA_PTR
  LDA D0_8BFC
  STA DATA_PTR_HI
  JMP DRAW_ENEMY_WALK
.D0_8BFB
  EQUB LO(ENEMY_WALK_06)
.D0_8BFC
  EQUB HI(ENEMY_WALK_06)

