; Shared framer. DATA_PTR is a word table. Frame is direction times 4 plus a frame index. ENEMY_PHASE_ANIM indexed by the phase selects a still frame or FRAME_CNT/8 mod 4. D0_92CD is the flip byte.
.DRAW_ENEMY_FRAME
  LDA #LO(ENEMY_FRAME_PTRS_18)
  STA DATA_PTR
  LDA #HI(ENEMY_FRAME_PTRS_18)
  STA DATA_PTR_HI
.L0_9288
  LDA #&01
  STA TEMP1
  LDY ENEMY_PHASE,X
  LDA ENEMY_PHASE_ANIM,Y
  BEQ L0_929D
  LDA FRAME_CNT
  LSR A
  LSR A
  LSR A
  AND #&03
  STA TEMP1
.L0_929D
  LDA ENEMY_X,X
  ABS_STA SPR_X
  LDA ENEMY_X_HI,X
  ABS_STA SPR_X_HI
  LDA ENEMY_Y,X
  ABS_STA SPR_Y
  LDY ENEMY_DIR,X
  LDA D0_92CD,Y
  ABS_STA SPR_FLIP
  LDA ENEMY_DIR,X
  ASL A
  ASL A
  ORA TEMP1
  ASL A
  TAY
  LDA (DATA_PTR),Y
  STA SPR_PTR
  INY
  LDA (DATA_PTR),Y
  STA SPR_PTR_HI
  JMP DRAW_METASPRITE
.D0_92CD
  EQUB &00,&00,&00,&40,&00,&00,&00,&00

