; 20 score-group bytes, one per enemy type. Added to the blast chain count in ENEMY_BLAST_OR_PLAYER.
.ENEMY_SCORE_INDEX
  EQUB &00,&00,&01,&00,&02,&02,&02,&02,&01,&02,&02,&06,&06,&02,&06,&06
  EQUB &00,&00,&00,&00

; Point DATA_PTR at the spawn list for area AREA_NUM and stage STAGE_NUM. Bytes are enemy types, ended by FF.
.LOAD_SPAWN_LIST
  ABS_LDA AREA_NUM
  ASL A
  TAX
  LDA AREA_SPAWN_PTRS,X
  STA DEST_PTR
  LDA D0_AD5B,X
  STA DEST_PTR_HI
  ABS_LDA STAGE_NUM
  ASL A
  TAY
  LDA (DEST_PTR),Y
  STA DATA_PTR
  INY
  LDA (DEST_PTR),Y
  STA DATA_PTR_HI
  RTS

; Six area pointers, then the stage list. Each list is type bytes ended by FF. The JP ROM uses a different pointer table.
.AREA_SPAWN_PTRS
  EQUB LO(D0_AD7E)
.D0_AD5B
  EQUB HI(D0_AD7E)
IF REGION = 2
  EQUB &93,&A8,&A3,&A8,&B3,&A8,&C3,&A8,&D3,&A8
ELIF REGION_JP
  EQUW D0_AD90
  EQUW JP_SPAWN_2
  EQUW D0_ADAE
  EQUW D0_ADBE
  EQUW D0_ADCE
ELSE
  EQUW D0_AD8E
  EQUW D0_AD9E
  EQUW D0_ADAE
  EQUW D0_ADBE
  EQUW D0_ADCE
ENDIF
  EQUW D0_AD68
.D0_AD68
  EQUW D0_AD78
  EQUW D0_AD7B
  EQUW D0_AD7A
  EQUW D0_AD7A
  EQUW D0_AD7A
  EQUW D0_AD7A
  EQUW D0_AD7A
  EQUW D0_AD7A
.D0_AD78
  EQUB &12,&13
.D0_AD7A
  EQUB &FF

; JP list starts at JP_SPAWN_0. US list starts at D0_AD7E. Later stage words differ where the lists moved.
.D0_AD7B
  EQUB &14,&15,&FF
IF REGION = 2
.D0_AD7E
  EQUW SPAWN_LIST_0_0
  EQUB &E7,&A8,&EC,&A8,&F1,&A8,&F7,&A8,&FD,&A8,&06,&A9
.D0_AD8E
  EQUB &0D,&A9
.D0_AD90
  EQUB &15,&A9,&1A,&A9,&21,&A9,&29,&A9,&31,&A9,&38,&A9,&41,&A9,&47,&A9
  EQUB &50,&A9,&55,&A9,&5C,&A9,&63,&A9,&6C,&A9,&73,&A9,&7C,&A9,&83,&A9
  EQUB &8C,&A9,&91,&A9,&98,&A9,&A1,&A9,&AA,&A9,&B1,&A9,&BA,&A9,&C3,&A9
  EQUB &CC,&A9,&D1,&A9,&DA,&A9,&E1,&A9,&E8,&A9,&F1,&A9,&FA,&A9,&03,&AA
  EQUB &0C,&AA,&15,&AA,&1E,&AA,&27,&AA,&30,&AA,&39,&AA,&42,&AA
.D0_AD9E
  EQUB &4B,&AA
ELIF REGION_JP

; JP area-0 spawn pointer list. US list is D0_AD7E.
.D0_AD7E
  EQUW SPAWN_LIST_0_0
  EQUW D0_ADE2
