; Add SCORE_ADD_TABLE indexed by TEMP1 into the decimal digits at SCORE_NOW. Skipped while DEMO_MODE is set. Caps at eight 9s.
.ADD_SCORE
  LDA DEMO_MODE
  BNE L0_AF8E
  LDY TEMP1
  LDA SCORE_ADD_TABLE,Y
  LDX #&02
.L0_AF5B
  CLC
  ADC SCORE_NOW,X
  LDY #&00
.L0_AF61
  STA SCORE_NOW,X
  SEC
  SBC #&0A
  BCC L0_AF6C

; (not seen executing during the coverage runs)
  INY
  BNE L0_AF61
.L0_AF6C
  TYA
  BEQ L0_AF8E

; (not seen executing during the coverage runs)
  INX
  CPX #&08
  BCC L0_AF5B
  LDA #&09
  STA SCORE_NOW
  STA SCORE_NOW_1
  STA SCORE_NOW_2
  STA SCORE_NOW_3
  STA SCORE_NOW_4
  STA SCORE_NOW_5
  STA SCORE_NOW_6
  STA SCORE_NOW_7
.L0_AF8E
  RTS

; Score added for TEMP1 0 through 10: 1, 2, 4, 8, 16, 32, 10, 20, 40, 80, 64.
.SCORE_ADD_TABLE
  EQUB &01,&02,&04,&08,&10,&20,&0A,&14,&28,&50,&40

; Metasprite pointers for the type-17 pickup drawn by DRAW_ENEMY_17. Indexed by ENEMY_SCORE.
.ITEM_SPRITE_PTRS
