; (not seen executing during the coverage runs)

; Credits. Clear the nametable, upload the credits CHR and palette, play sound 18 hex, and scroll until Start.
.SHOW_CREDITS
  JSR PPU_OFF
  JSR NMI_OFF
  LDA #&00
  JSR FILL_NAMETABLE
  JSR CLEAR_ATTRS
  JSR LOAD_CREDITS_GFX
  JSR NMI_ON
  JSR CLEAR_SCROLL
  LDA #&00
  STA CREDITS_TICK
  STA CREDITS_ROW
  LDA #&01
  STA CREDITS_MODE
  JSR PPU_ON
  JSR MARK_PALETTE
  LDA #&18
  JSR AUDIO_CALL
.L0_B037
  JSR WAIT_NMI
  JSR TICK_CREDITS
  JSR MARK_OAM
  LDA CREDITS_MODE
  BNE L0_B037
  LDA JOY_NEW
  AND #&10
  BEQ L0_B037
  JSR FADE_PALETTE
  JMP PPU_OFF

; Upload the RLE CHR at A486 and four palette rows from bank 4. The palette address differs on the JP ROM.
.LOAD_CREDITS_GFX
  LDA #LO(UI_SPR_CHR)
  STA DATA_PTR
  LDA #HI(UI_SPR_CHR)
  STA DATA_PTR_HI
  LDA #&00
  STA DEST_PTR
  LDA #&10
  STA DEST_PTR_HI
  LDX #&06
  LDY #&FF
  JSR UPLOAD_CHR_RLE
  LDA #LO(STORY_MODE_PAL)
  STA PAL_SRC
  LDA #HI(STORY_MODE_PAL)
  STA PAL_SRC_HI
  LDA #&00
  LDX #&04
  FARCALL 4, COPY_PAL_ROWS
  JMP MIRROR_BG_COLOR

; CREDITS_MODE = 1 scrolls up and queues the next credits line, 26 tiles, from the pointer table at B117. A 0000 pointer switches to mode 2, which waits and then queues the final line.

; Credits line pointer base. JP adds 1C then AC (table at AC1C). US adds 17 then B1 (table at B117).
.TICK_CREDITS
  LDA CREDITS_MODE
  BEQ L0_B0E1
  CMP #&02
  BEQ L0_B0F0
  LDA FRAME_CNT
  LSR A
  BCC L0_B0E1
  INC SCROLL_Y
  LDA SCROLL_Y
  CMP #&F0
  BCC L0_B09B
  LDA #&00
  STA SCROLL_Y
.L0_B09B
  INC CREDITS_TICK
  LDA CREDITS_TICK
  AND #&07
  BNE L0_B0E1
  LDA #&00
  STA DEST_PTR_HI
  LDA CREDITS_ROW
  INC CREDITS_ROW
  ASL A
  ROL DEST_PTR_HI
  CLC
  ADC #LO(D0_B117)
  STA DEST_PTR
  LDA DEST_PTR_HI
  ADC #HI(D0_B117)
  STA DEST_PTR_HI
  LDY #&00
  LDA (DEST_PTR),Y
  STA DATA_PTR
  INY
  LDA (DEST_PTR),Y
  STA DATA_PTR_HI
  ORA DATA_PTR
  BEQ L0_B0E2
  LDX #&03
  LDA SCROLL_Y
  LSR A
  LSR A
  LSR A
  TAY
  JSR XY_TO_NT_ADDR
  LDA #&00
  STA PPU_RUN_CTRL
  LDX #&1A
  JMP QUEUE_PPU_RUN
.L0_B0E1
  RTS
.L0_B0E2
  LDA #&02
  STA CREDITS_MODE
  LDA #&00
  STA CREDITS_TICK
  STA CREDITS_ROW
  RTS
.L0_B0F0
  INC CREDITS_TICK
  LDA CREDITS_TICK
  CMP #&20
  BCC L0_B0E1
  LDA #&00
  STA CREDITS_MODE
  LDX #&03
  LDY #&17
  JSR XY_TO_NT_ADDR
  LDA #LO(D0_B4B1)
  STA DATA_PTR
  LDA #HI(D0_B4B1)
  STA DATA_PTR_HI
  LDA #&00
  STA PPU_RUN_CTRL
  LDX #&1A
  JMP QUEUE_PPU_RUN
